-- Owners whose own page says American / NMJL (scripts/verify-owners.mjs), with their ready sessions
UPDATE "Club" SET "status" = 'ACTIVE', "lastVerifiedAt" = '2026-11-21', "description" = CASE WHEN "description" LIKE '%American/NMJL not stated%' THEN trim(replace("description", 'American/NMJL not stated on the club''s page.', '') || ' Its own page says: "Learn to play American Mah Jongg following the National Mah Jongg League rules with Nancy Esposito. Experience the excitement of learning this historic game that is now popular with adults of all ages"') ELSE "description" END, "updatedAt" = CURRENT_TIMESTAMP WHERE "slug" = 'commack-smithtown-library-commack-branch-mah-jongg' AND "status" = 'NEEDS_REVIEW'; -- Smithtown Library - Commack Branch Mah Jongg (Commack, NY): "Learn to play American Mah Jongg following the National Mah Jongg League rules with Nancy Esposito. Experience the excitement of learning this historic game that is now popular with adults of all ages" https://www.smithlib.org/events

